/* C's BIT/GENMASK helpers are expressed directly as u32 operations here. */
macro_rules! bit { ($n:expr) => { 1u32 << $n }; }
macro_rules! mask { ($hi:expr, $lo:expr) => { (((1u32 << ($hi + 1)) - 1) & !((1u32 << $lo) - 1)) }; }

